// 领域词（本仓自建）并进同一张表：候选边界只由「表里有没有这个词」决定。
for (const w of CJK_DOMAIN) CJK_LEXICON.add(w)

/** 本项目补充的常用词（jieba 频次表里缺失或过低的词；常用词本身不构成版权，见 THIRD-PARTY.md）。 */
for (const w of ['文档', '补全', '变量', '管理', '系统', '上下文', '输入框', '插件', '会话', '词表', '候选', '配对', '环绕', '光标', '补丁', '仓库', '组织', '分支', '提交', '合并', '排序', '文档管理', '完整词义', '分段', '解析']) CJK_LEXICON.add(w)
export const PROJECT_WORDS = 25

/** 词表里最长的词长：分词与候选都按它上限走，不写死数字。 */
let _maxLen = 0
for (const w of CJK_LEXICON) if (w.length > _maxLen) _maxLen = w.length
export const CJK_MAX_LEN = _maxLen

export function lexiconMatches(prefix, cap) {
  var p = String(prefix || '')
  if (!p) return []
  var out = []
  var it = CJK_LEXICON.values()
  for (var r = it.next(); !r.done; r = it.next()) {
    var w = r.value
    if (w.length > p.length && w.indexOf(p) === 0) out.push(w)
  }
  out.sort(function (a, b) { return b.length - a.length || (a < b ? -1 : 1) })
  return out.slice(0, cap || 8)
}
/** 「完整词义」闸：前缀本身必须是词典里的词，碎片（如「档管」）一律 false。 */
export function isCompleteWord(prefix) {
  var p = String(prefix || '')
  return p.length >= 2 && CJK_LEXICON.has(p)
}
export const CJK_LEXICON_SOURCE = { repo: 'fxsjy/jieba', license: 'MIT', file: 'extra_dict/dict.txt.big', kept: 30000 }
